ions.EncoreMove:f.Conditions.LastMove);Theme.Row(t,"앙코르 기술",encoreMove);AddNum(t,"구르기 명중",f.Conditions.RolloutCount,4);rolloutMove=Theme.Combo(new[]{"없음","구르기","아이스볼"},string.IsNullOrEmpty(f.Conditions.RolloutMove)?"없음":f.Conditions.RolloutMove);Theme.Row(t,"연속 사용 기술",rolloutMove);split.Panel1.Controls.Add(t);
