   major.SelectedIndexChanged+=(s,e)=>Preview();foreach(var n in numbers.Values)n.ValueChanged+=(s,e)=>Preview();foreach(var c in flags.Values)c.CheckedChanged+=(s,e)=>Preview();attractSide.SelectedIndexChanged+=(s,e)=>Preview();rampageMove.SelectedIndexChanged+=(s,e)=>Preview();encoreMove.SelectedIndexChanged+=(s,e)=>Preview();rolloutMove.SelectedIndexChanged+=(s,e)=>Preview();mindReaderSide.SelectedIndexChanged+=(s,e)=>Preview();disabledMove.TextChanged+=(s,e)=>Preview();sleep.ValueChanged+=(s,e)=>Preview();toxic.ValueChanged+=(s,e)=>Preview();apply.Click+=(s,e)=>{if((int)numbers["사슬묶기"].Value>0&&string.IsNullOrEmpty(original.Conditions.LastMove)){GameDialog.Show(this,"마지막으로 사용한 기술이 없어 사슬묶기를 적용할 수 없습니다.","상태 적용 실패");return;}var draft=Read();if(draft.Conditions.EncoreTurns>0&&(original.Conditions.EncoreTurns<=0||draft.Conditions.EncoreMove!=original.Conditions.EncoreMove)){int turns=draft.Conditions.EncoreTurns;string selected=draft.Conditions.EncoreMove;Mechanics.ClearEncore(draft,null);var messages=new List<string>();if(!Mechanics.ApplyEncore(draft,messages,turns,selected)){GameDialog.Show(this,string.Join("\n",messages),"상태 적용 실패");return;}}if(draft.Status=="잠듦"&&original.Status!="잠듦"&&!draft.Conditions.SleepFromRest){string sleepBlock=Mechanics.SleepBlock(draft,rules);if(sleepBlock.Length>0){GameDialog.Show(this,sleepBlock,"상태 적용 실패");return;}}if(draft.Status!=original.Status&&draft.Status!="정상"&&!force.Checked){var clear=draft.Copy();clear.Status="정상";string reason=Mechanics.StatusBlock(clear,opponent,draft.Status,rules,draft.Conditions.SleepFromRest);if(reason.Length>0){GameDialog.Show(this,reason+"\n예외 판정이라면 '수동 강제 적용'을 선택하세요.","상태이상 무효");return;}}Value=draft;DialogResult=DialogResult.OK;Close();};Preview();}
  void AddNum(TableLayoutPanel t,string key,int value,int max){var n=Theme.Number(value,0,max);numbers[key]=n;Theme.Row(t,(key=="죽음의 카운트"?"죽음 카운트":key)+(key=="대타 HP"||key=="죽음의 카운트"||key=="구르기 명중"?"":new[]{"침묵","망각","회복봉인","사슬묶기","조이기","요격","분노","난동부리기","앙코르"}.Contains(key)?" T":" 남은 턴"),n);}
