  Fighter Read(){var f=original.Copy();f.Status=(string)major.SelectedItem;var c=f.Conditions;c.SleepTurns=(int)sleep.Value;if(f.Status=="잠듦")c.SleepStart=c.SleepTurns;c.ToxicStage=(int)toxic.Value;c.Confusion=(int)numbers["혼란"].Value;c.Taunt=(int)numbers["도발"].Value;c.Substitute=(int)numbers["대타 HP"].Value;c.Protect=flags["방어"].Checked;c.Flinch=flags["풀죽음"].Checked;c.Recharge=flags["반동대기"].Checked;c.Seed=flags["씨뿌리기"].Checked;c.Curse=flags["저주"].Checked;c.AquaRing=flags["아쿠아링"].Checked;c.Ingrain=flags["뿌리박기"].Checked;c.FlashFire=flags["불꽃 흡수 강화"].Checked;c.BalloonPopped=flags["풍선 터짐"].Checked;c.Heated=flags["가열"].Checked;c.Chilled=flags["냉각"].Checked;c.Charged=flags["충전"].Checked;string swap=flags["악인"].Checked?"악인":flags["침수"].Checked?"침수":flags["송전"].Checked?"송전":"";Mechanics.ClearTypeSwap(f,null);if(swap.Length>0)Mechanics.SetTypeSwap(f,swap,null);c.Silenced=(int)numbers["침묵"].Value;c.Forgotten=(int)numbers["망각"].Value;c.HealBlock=(int)numbers["회복봉인"].Value;c.Disabled=(int)numbers["사슬묶기"].Value;c.DisabledMove=c.Disabled>0?(disabledMove.Text??"").Trim():"";if(c.Disabled>0&&string.IsNullOrEmpty(c.LastMove))c.Disabled=0;if(c.Disabled>0&&c.DisabledMove.Length==0)c.DisabledMove=c.LastMove;if(c.Disabled==0)c.DisabledMove="";c.Bound=(int)numbers["조이기"].Value;c.Tormented=flags["트집"].Checked;c.MeanLook=flags["검은눈빛"].Checked;c.Bomb=flags["폭탄"].Checked;if(c.Bomb&&!original.Conditions.Bomb)c.BombSetTurn=rules.Turn;c.Intercept=(int)numbers["요격"].Value;c.Rage=(int)numbers["분노"].Value;int sourceSide=mindReaderSide.SelectedIndex-1;if(sourceSide<0)Mechanics.ClearMindReader(f,null);else if(sourceSide!=original.Conditions.MindReaderSide)Mechanics.ApplyMindReader(f,sourceSide,rules);c.HelpingHand=flags["도우미"].Checked;c.Curled=flags["웅크리기"].Checked;c.AttractSide=attractSide.SelectedIndex-1;if(flags["동면"].Checked){if(c.Hibernate<=0)Mechanics.ApplyHibernate(f,rules);}else c.Hibernate=0;c.DeathCount=(int)numbers["죽음의 카운트"].Value;c.RampageTurns=(int)numbers["난동부리기"].Value;c.RampageMove=c.RampageTurns>0?(string)rampageMove.SelectedItem:"";c.SleepFromRest=f.Status=="잠듦"&&flags["잠자기 수면"].Checked;c.EncoreTurns=(int)numbers["앙코르"].Value;c.EncoreMove=c.EncoreTurns>0?(string)encoreMove.SelectedItem??"":"";c.RolloutMove=(string)rolloutMove.SelectedItem=="없음"?"":(string)rolloutMove.SelectedItem;c.RolloutCount=c.RolloutMove.Length>0?(int)numbers["구르기 명중"].Value:0;return f;}
  void Preview(){info.SetLog(RuleBook.Report(db,Read(),opponent,rules));}
