 class RulesForm:Form {
  public Rules Value;public RulesForm(Rules r){Load+=(s,e)=>Theme.Enlarge(this);Value=r.Copy();Text="날씨 / 필드 / 계산 설정";Size=new Size(920,740);MinimumSize=new Size(800,650);StartPosition=FormStartPosition.CenterParent;Font=Theme.UI();BackColor=Color.White;var split=new SplitContainer{Size=new Size(900,620),Dock=DockStyle.Fill,SplitterDistance=400,FixedPanel=FixedPanel.Panel1};split.Panel1.AutoScroll=true;var details=new LogView{Dock=DockStyle.Fill};details.SetLog(RuleBook.WeatherHelp);split.Panel2.Padding=new Padding(16);split.Panel2.Controls.Add(details);var t=Theme.Table();var weather=Theme.Combo(Mechanics.Weathers,r.Weather);var terrain=Theme.Combo(Mechanics.Terrains,r.Terrain);var wt=Theme.Number(r.WeatherTurns,0,99);var tt=Theme.Number(r.TerrainTurns,0,99);var trick=Theme.Number(r.TrickRoom,0,99);var gravity=Theme.Number(r.Gravity,0,99);var s1r=Theme.Number(r.Sides[0].Reflect,0,99);var s1l=Theme.Number(r.Sides[0].LightScreen,0,99);var s1i=Theme.Number(r.Sides[0].IceWall,0,99);var s1t=Theme.Number(r.Sides[0].Tailwind,0,99);var s2r=Theme.Number(r.Sides[1].Reflect,0,99);var s2l=Theme.Number(r.Sides[1].LightScreen,0,99);var s2i=Theme.Number(r.Sides[1].IceWall,0,99);var s2t=Theme.Number(r.Sides[1].Tailwind,0,99);var critical=Check("급소 2배 (시트)",r.Critical);var hp=Check("HP 레벨 보정",r.HPCorrection);var sheet=Check("시트 필드 배율",r.SheetTerrain);var bonus=Theme.Number((decimal)r.PowerBonus,-999,999);var power=Theme.Number((decimal)r.PowerMultiplier,0,100,2);var damage=Theme.Number((decimal)r.DamageMultiplier,0,100,2);var stab=Theme.Number((decimal)r.Stab,0,10,2);var correction=Theme.Number((decimal)r.LevelCorrection,0,10,2);var slight=Theme.Number(r.SlightSpeciesBonus,0,999);
   Theme.Row(t,"날씨",weather);Theme.Row(t,"날씨 잔여 턴",wt);Theme.Row(t,"필드",terrain);Theme.Row(t,"필드 잔여 턴",tt);Theme.Row(t,"트릭룸 잔여 턴",trick);Theme.Row(t,"중력 잔여 턴",gravity);Theme.Row(t,"1팀 리플렉터",s1r);Theme.Row(t,"1팀 빛의장막",s1l);Theme.Row(t,"1팀 얼음의벽",s1i);Theme.Row(t,"1팀 순풍",s1t);Theme.Row(t,"2팀 리플렉터",s2r);Theme.Row(t,"2팀 빛의장막",s2l);Theme.Row(t,"2팀 얼음의벽",s2i);Theme.Row(t,"2팀 순풍",s2t);Theme.Row(t,"급소 2배 (시트)",critical);Theme.Row(t,"필드 규칙",sheet);Theme.Row(t,"위력 고정치",bonus);Theme.Row(t,"위력 배율",power);Theme.Row(t,"대미지 배율",damage);Theme.Row(t,"자속 (0=자동)",stab);Theme.Row(t,"레벨 보정 %",correction);Theme.Row(t,"체력 보정",hp);Theme.Row(t,"종족치 ‘조금’",slight);split.Panel1.Controls.Add(t);Controls.Add(split);var apply=new FlatButton{Text="적용",Primary=true,Dock=DockStyle.Bottom,Height=48};Controls.Add(apply);weather.SelectedIndexChanged+=(s,e)=>{wt.Value=new[]{"큰가뭄","강한 비","난기류"}.Contains((string)weather.SelectedItem)?0:5;};terrain.SelectedIndexChanged+=(s,e)=>tt.Value=5;apply.Click+=(s,e)=>{var next=r.Copy();next.Weather=(string)weather.SelectedItem;next.Terrain=(string)terrain.SelectedItem;next.WeatherTurns=(int)wt.Value;next.TerrainTurns=(int)tt.Value;next.TrickRoom=(int)trick.Value;next.Gravity=(int)gravity.Value;next.Critical=critical.Checked;next.HPCorrection=hp.Checked;next.SheetTerrain=sheet.Checked;next.PowerBonus=(double)bonus.Value;next.PowerMultiplier=(double)power.Value;next.DamageMultiplier=(double)damage.Value;next.Stab=(double)stab.Value;next.LevelCorrection=(double)correction.Value;next.SlightSpeciesBonus=(int)slight.Value;next.Sides[0].Reflect=(int)s1r.Value;next.Sides[0].LightScreen=(int)s1l.Value;next.Sides[0].IceWall=(int)s1i.Value;next.Sides[0].Tailwind=(int)s1t.Value;next.Sides[1].Reflect=(int)s2r.Value;next.Sides[1].LightScreen=(int)s2l.Value;next.Sides[1].IceWall=(int)s2i.Value;next.Sides[1].Tailwind=(int)s2t.Value;Value=next;DialogResult=DialogResult.OK;Close();};}
  static PixelCheckBox Check(string text,bool value){return new PixelCheckBox{Text=text,Checked=value,Font=Theme.Input(),Dock=DockStyle.Fill};}
